using DeathBySeventhsDawn.Knowledge;
using DeathBySeventhsDawn.TimeSystem;
[InitializeOnLoad]public static class VerifyTutorialLogic
{
    const string TestKey="TutorialLogicAcceptance";static IEnumerator steps;static double next,deadline;static int count;static string error;static Keyboard keyboard;static bool pendingInput;static Key pendingKey;
    static ProgressionState State=>(ProgressionState)typeof(GameManager).GetProperty("State",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).GetValue(GameManager.Instance);
    static object Field(object o,string n)=>o.GetType().GetField(n,System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).GetValue(o);
    static void Call(object o,string n)=>o.GetType().GetMethod(n,System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).Invoke(o,null);
    static StoryJournal Journal=>UnityEngine.Object.FindAnyObjectByType<StoryJournal>();
    static void Check(bool ok,string reason){count++;if(!ok)throw new Exception(reason);}
    static VerifyTutorialLogic(){InputSystem.onBeforeUpdate+=ApplyPendingInput;EditorApplication.update+=Tick;EditorApplication.playModeStateChanged+=s=>{if(!SessionState.GetBool(TestKey,false))return;if(s==PlayModeStateChange.EnteredPlayMode){steps=Steps();next=EditorApplication.timeSinceStartup+3;deadline=next+150;count=0;error=null;}if(s==PlayModeStateChange.ExitingPlayMode)Restore();};Application.logMessageReceived+=(m,t,l)=>{if(steps!=null&&(l==LogType.Error||l==LogType.Exception)&&!t.Contains("UnityEditor.Search.SearchDatabase"))error=m;};}
    [MenuItem("Prototype/Test tutorial state logic without keyboard")]
    public static void Run(){if(EditorApplication.isPlaying)return;if(SessionState.GetBool(TestKey,false))Restore();foreach(var suffix in new[]{"",".bak",".tmp"}){var p=ProgressionSave.PathName+suffix;SessionState.SetString(TestKey+suffix,File.Exists(p)?Convert.ToBase64String(File.ReadAllBytes(p)):"");}SessionState.SetInt(TestKey+"Focus",(int)InputSystem.settings.backgroundBehavior);SessionState.SetInt(TestKey+"Lang",PlayerPrefs.GetInt("Story.Language",0));SessionState.SetFloat(TestKey+"Volume",GameSettingsUI.MasterVolume);PlayerPrefs.SetInt("Story.Language",0);SessionState.SetBool(TestKey+"Bg",PlayerSettings.runInBackground);Application.runInBackground=true;SessionState.SetBool(TestKey,true);SessionState.SetBool(DayOneSupernovaEvent.SuppressionKey,true);ProgressionSave.Write(new ProgressionState());EditorSceneManager.OpenScene("Assets/Scenes/Apartment/Bedroom.unity");EditorApplication.isPlaying=true;}
    static void Tick(){if(EditorApplication.isCompiling||EditorApplication.isUpdating)return;if(steps==null){if(!EditorApplication.isPlaying&&File.Exists("../tutorial-logic-request.txt")){File.Delete("../tutorial-logic-request.txt");Run();}return;}if(EditorApplication.timeSinceStartup<next)return;try{if(error!=null)throw new Exception(error);if(EditorApplication.timeSinceStartup>deadline)throw new Exception("Acceptance timeout");if(steps.MoveNext())next=EditorApplication.timeSinceStartup+(float)steps.Current;else Finish(null);}catch(Exception e){Finish(e.ToString());}}
    static void ApplyPendingInput(){if(!pendingInput||InputState.currentUpdateType!=InputUpdateType.Dynamic||keyboard==null)return;keyboard.MakeCurrent();InputSystem.QueueStateEvent(keyboard,pendingKey==Key.None?new KeyboardState():new KeyboardState(pendingKey));pendingInput=false;}
    static void Press(Key key){if(Application.isBatchMode){pendingKey=key;pendingInput=true;}else{keyboard.MakeCurrent();InputSystem.QueueStateEvent(keyboard,new KeyboardState(key));}}static void Release(){if(Application.isBatchMode){pendingKey=Key.None;pendingInput=true;}else InputSystem.QueueStateEvent(keyboard,new KeyboardState());}
    static void Place(Vector2 p){var g=GameObject.FindWithTag("Player");g.transform.position=p;g.GetComponent<Rigidbody2D>().position=p;Physics2D.SyncTransforms();}
    static void Capture(string name){if(!Application.isBatchMode)ScreenCapture.CaptureScreenshot("../tutorial-"+name+".png");}
    static void ClosePage(){var t=typeof(StoryJournal).GetNestedType("Page",System.Reflection.BindingFlags.NonPublic);typeof(StoryJournal).GetMethod("SetPage",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).Invoke(Journal,new[]{Enum.Parse(t,"None")});}
    static IEnumerator Steps(){
        InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;if(StoryText.English)StoryText.ToggleLanguage();while(GameManager.Instance==null)yield return .2f;
        var routine=MorningRoutine.Instance;
        Check(State.version==2&&!State.journalUnlocked&&!State.investigationUnlocked&&!State.tutorialComplete,"Fresh journey locks journal, investigation and free-time furniture");
        Journal.ShowJournal();Check(Field(Journal,"page").ToString()=="Dream","Journal cannot open before it is acquired");Check(!Investigation.Collect("tank-label"),"Collection cannot occur before investigation lesson");
        Check(Resources.Load<Sprite>("Tutorial/FridgeOpen")!=null,"Opened-fridge sprite imported");Check(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Story/LobbyNoticeFlyer.prefab")!=null,"Flyer retained as future lobby prefab");
        MainMenuUI.ReturnToMainMenu();yield return 5f;
        Check(StoryText.Current.mainMenu.title=="七日"&&StoryText.Current.mainMenu.subtitle=="SEVEN DAY","Chinese title has uppercase English subtitle");
        GameSettingsUI.Show();GameSettingsUI.SetVolume(.37f);StoryText.ToggleLanguage();yield return .3f;
        Check(GameSettingsUI.IsOpen&&StoryJournal.WorldBlocked,"Settings block gameplay");Check(Mathf.Abs(GameSettingsUI.MasterVolume-.37f)<.001f&&Mathf.Abs(AudioListener.volume-.37f)<.001f,"Volume applies to actual audio listener and persists");
        Check(StoryText.Current.mainMenu.title=="SEVEN DAY"&&GameTypography.Current==GameTypography.English&&GameTypography.English.fontNames.Contains("Times New Roman"),"English title and formal font selection");
        Check(Investigation.Catalog.evidence.All(e=>!string.IsNullOrWhiteSpace(e.title)),"Every English evidence ID resolves to localized text");MainMenuUI.Instance.StartGame();Check(!MainMenuUI.IsOpening,"Start action cannot bypass open settings");GameSettingsUI.Hide();yield return .3f;Check(MainMenuUI.IsVisible&&!GameSettingsUI.IsOpen,"Closing settings returns to title");StoryText.ToggleLanguage();GameSettingsUI.SetVolume(SessionState.GetFloat(TestKey+"Volume",1));
        var audio=ApartmentAudio.Instance;Check(audio.Ready,"Audio setup survives settings changes");MainMenuUI.Instance.StartGame();yield return 6.5f;Check(MainMenuUI.IsOpening&&audio.ScreamPlaying,"Opening and actual scream source play");yield return 5f;Check(Field(Journal,"page").ToString()=="Dream"&&!MainMenuUI.IsOpening,"Opening leads to dream");
        Call(Journal,"WakeUp");yield return 4f;var player=GameObject.FindWithTag("Player");Check(State.dreamSeen&&routine.Stage==2&&Vector2.Distance(player.transform.position,routine.Bedside)<.2f,"Wake completes beside bed");Check(player.GetComponent<Rigidbody2D>().simulated&&CultNeighbor.Instance.ImpactCount>0,"Wake restores motion and plays hammer cues");Check(State.journal.Count==0&&!State.journalUnlocked,"Wake and dream do not reveal journal");
        var window=UnityEngine.Object.FindAnyObjectByType<WindowLookout2D>();var before=player.transform.position;Place((Vector2)window.transform.position+Vector2.down*1.2f);yield return .25f;Check(!window.CanInteract&&!window.TryOpen(),"Window rejects distant player");Place((Vector2)window.transform.position+Vector2.down*.25f);yield return .25f;Check(window.TryOpen(),"Window remains accessible at close range");window.CloseView();Place(before);
        SceneManager.LoadScene("Corridor");yield return 5f;Check(CultNeighbor.WorldBlocked&&Field(CultNeighbor.Instance,"view").ToString()=="DayOne","Neighbour warns automatically after protagonist exits");Check(GameObject.Find("401 flyer")==null&&!Investigation.Has("401-flyers"),"Fourth-floor flyer removed");for(int i=0;i<StoryText.Current.cult.dayOne.Length;i++)CultNeighbor.Instance.Advance();Check(State.cultDayOneTalked&&routine.Stage==3&&State.journal.Count==0,"Completed conversation leads home without journal entry");
        SceneManager.LoadScene("LivingRoom");yield return .7f;var fridge=GameObject.Find("Refrigerator");var sr=fridge.GetComponent<SpriteRenderer>();var closed=sr.sprite;var b=sr.bounds;Place(new Vector2(fridge.transform.position.x,b.min.y-.3f));yield return .3f;
        Check(routine.OpenFridge(),"Fridge opens after neighbour guide");Check(sr.sprite==Resources.Load<Sprite>("Tutorial/FridgeOpen")&&sr.sprite!=closed&&State.fridgeDoorOpen,"Fridge swaps to actual open sprite and saves door state");yield return 1f;
        var news=DayOneSupernovaEvent.Instance;for(int wait=0;wait<30&&!news.IsPresenting&&routine.Stage==4;wait++)yield return .1f;Check(news.IsPresenting&&State.dayOneNewsStarted&&routine.Stage==4,"First fridge opening starts news once: stage="+routine.Stage+" started="+State.dayOneNewsStarted+" seen="+State.dayOneSupernovaSeen+" activity="+Field(routine,"activity")+" age="+Field(routine,"age")+" Days="+TimeManager.Instance.Days);Check(!routine.OpenFridge()&&!news.PlayFromFridge(),"Concurrent fridge/news actions are rejected");
        Check(!UnityEngine.Object.FindAnyObjectByType<FurnitureInteraction>().CollectNews()&&State.journal.Count==0&&!State.journalUnlocked,"Television cannot record to a nonexistent journal");
        news.Advance();Check(news.PageIndex==1&&ProgressionSave.Load().newsPage==1,"News page persists");SceneManager.LoadScene("Bedroom");yield return .4f;SceneManager.LoadScene("LivingRoom");yield return .7f;
        Check(news.IsPresenting&&news.PageIndex==1,"Interrupted news resumes without restarting");Check(GameObject.Find("Refrigerator").GetComponent<SpriteRenderer>().sprite==Resources.Load<Sprite>("Tutorial/FridgeOpen"),"Fridge remains open across scene reload");
        for(int i=1;i<4;i++)news.Advance();yield return .4f;Check(State.dayOneSupernovaSeen&&routine.Stage==5&&State.journal.Count==0,"Finished news leads to sofa with no automatic entry");
        fridge=GameObject.Find("Refrigerator");Place(new Vector2(fridge.transform.position.x,fridge.GetComponent<SpriteRenderer>().bounds.min.y-.3f));yield return .3f;
        for(int i=0;i<3;i++){Check(routine.OpenFridge(),"Repeat fridge toggle "+i);yield return 1f;Check(!news.IsPresenting&&routine.Stage==5&&State.newsPage==4,"Repeated fridge cannot rewind bulletin or tutorial "+i);}
        Check(TimeManager.Instance.Days==1&&TimeManager.Instance.Period==TimePeriod.Morning,"Fridge never consumes a time period");
        var sofa=GameObject.Find("Old sofa").GetComponent<SpriteRenderer>().bounds;Place(new Vector2(sofa.center.x,sofa.min.y-.3f));yield return .3f;Check(routine.CanNap&&routine.BeginNap(),"Sofa rest is available after news");yield return 3.8f;
        Check(routine.Stage==6&&TimeManager.Instance.Days==1&&TimeManager.Instance.Period==TimePeriod.Evening,"Sofa sleep advances to same-day evening");Check(!State.journalUnlocked&&State.journal.Count==0,"Sofa sleep alone does not unlock journal");
        SceneManager.LoadScene("Bedroom");yield return .6f;Place(new Vector2(2.7f,-1.1f));yield return .3f;Check(routine.CanWrite&&routine.BeginWriting(),"Desk writing begins only at the desk");yield return 2.3f;
        Check(State.journalUnlocked&&!State.investigationUnlocked&&routine.Stage==7&&Field(Journal,"page").ToString()=="Diary","Writing unlocks and opens the journal, leaving investigation locked");
        Check(State.journal.Count==4&&State.journal.Select(e=>e.id).Distinct().Count()==4&&Investigation.Has("401-warning")&&Investigation.Has("skt079-broadcast")&&Investigation.Has("my-observation-notes"),"Initial day-one information is inserted once");Check(!Investigation.Has("401-flyers")&&!Investigation.Collect("apartment-telescope"),"No archived flyer or premature telescope collection");
        StoryText.ToggleLanguage();Check(Investigation.LocalTitle("first-evening-journal","")=="The first evening"&&Investigation.Title("my-observation-notes")=="Old observation records","Initial journal localizes live");StoryText.ToggleLanguage();ClosePage();yield return .3f;Check(!routine.BeginWriting(),"Initial journal cannot be duplicated by writing again");
        SceneManager.LoadScene("Balcony");yield return .6f;Place(Resources.Load<StoryContent>("StoryContent").telescopePosition);yield return .3f;Call(Journal,"OpenTelescope");Check(!Journal.CollectTelescopeEvidence(),"Collection remains locked before first observation");Call(Journal,"ObserveTelescope");yield return .3f;
        Check(State.investigationUnlocked&&routine.Stage==8&&!Journal.IsRevelation&&!Investigation.Has("apartment-telescope"),"First evening observation teaches investigation without ancient revelation or automatic collection");
        Check(Journal.CollectTelescopeEvidence()&&!Journal.CollectTelescopeEvidence()&&routine.Stage==9&&!State.tutorialComplete,"Telescope collection is explicit and deduplicated");ClosePage();yield return .3f;
        Check(Investigation.Connect("my-observation-notes","apartment-telescope",false),"Tentative link can be created");yield return .2f;Check(!State.tutorialComplete,"Tentative link does not finish tutorial");Check(Investigation.Connect("my-observation-notes","apartment-telescope",true),"Correct deduction can be confirmed");yield return .3f;Check(State.tutorialComplete&&routine.Stage==10&&Investigation.Has("deduction-astronomy"),"Confirmed deduction completes investigation tutorial");
        Call(Journal,"OpenTelescope");Call(Journal,"ObserveTelescope");Check(!((string)Field(Journal,"telescopeMessage")).Contains(StoryText.Current.morning.investigate)&&routine.Stage==10,"Completed tutorial does not repeat telescope lesson");ClosePage();var partial=new ProgressionState{morningStage=4,dayOneSupernovaSeen=true};Investigation.Normalize(partial);Check(partial.morningStage==5,"Completed news with an old intermediate stage recovers to sofa");var saved=ProgressionSave.Load();Check(saved.version==2&&saved.journalUnlocked&&saved.investigationUnlocked&&saved.tutorialComplete&&saved.dayOneSupernovaSeen&&saved.newsPage==4,"Tutorial and news progress survive save/load");
        var legacy=JsonUtility.FromJson<ProgressionState>("{\"version\":1,\"badEndingOne\":true,\"journal\":[{\"id\":\"skt079-broadcast\"}],\"knowledgeIds\":[]}");Investigation.Normalize(legacy);Check(legacy.version==2&&legacy.journal.Count==1&&legacy.journalUnlocked&&legacy.tutorialComplete&&legacy.morningStage==10&&legacy.badEndingOne,"Old collected/ended saves migrate without losing access or reentering tutorial");
        GameSettingsUI.Show();GameManager.Instance.StartNewJourney();yield return .6f;Check(!GameSettingsUI.IsOpen,"New journey closes settings");Check(!State.journalUnlocked&&!State.investigationUnlocked&&!State.tutorialComplete&&!State.dayOneNewsStarted&&!State.fridgeOpened&&!State.fridgeDoorOpen&&State.newsPage==0&&State.journal.Count==0&&routine.Stage==0,"New journey clears every tutorial, news and fridge state");Check(Field(Journal,"page").ToString()=="Dream"&&TimeManager.Instance.Period==TimePeriod.Morning,"Full reset returns to initial dream and morning");Check(error==null,"No runtime game errors");
    }
    static void Finish(string failure){steps=null;File.WriteAllText("../tutorial-logic-validation.txt",failure==null?"LOGIC PASS: "+count+" checks; settings and serif fonts; uppercase title; hidden journal; archived lobby flyer; real fridge sprite; once-only news and interruption recovery; sofa to evening; desk writing and deduplicated initial information; telescope investigation and confirmed connection; persistence, migration and complete reset.":"FAIL: "+failure);EditorApplication.isPlaying=false;Restore();if(Application.isBatchMode)EditorApplication.Exit(failure==null?0:1);}
    static void Restore(){if(!SessionState.GetBool(TestKey,false))return;SessionState.SetBool(TestKey,false);InputSystem.settings.backgroundBehavior=(InputSettings.BackgroundBehavior)SessionState.GetInt(TestKey+"Focus",0);if(keyboard!=null&&keyboard.added)InputSystem.RemoveDevice(keyboard);keyboard=null;foreach(var suffix in new[]{"",".bak",".tmp"}){var p=ProgressionSave.PathName+suffix;var b=SessionState.GetString(TestKey+suffix,"");if(b.Length>0)File.WriteAllBytes(p,Convert.FromBase64String(b));else if(File.Exists(p))File.Delete(p);}PlayerPrefs.SetInt("Story.Language",SessionState.GetInt(TestKey+"Lang",0));GameSettingsUI.SetVolume(SessionState.GetFloat(TestKey+"Volume",1));PlayerPrefs.Save();Application.runInBackground=SessionState.GetBool(TestKey+"Bg",false);PlayerSettings.runInBackground=SessionState.GetBool(TestKey+"Bg",false);SessionState.SetBool(DayOneSupernovaEvent.SuppressionKey,false);steps=null;}
}
